            ctx.fill();

            if (isLast && chartState.hoveredIdx == null) {
              ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, 0.5)`;
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.arc(pt.x, pt.y, 7, 0, Math.PI * 2);
              ctx.stroke();
