          ctx.strokeStyle = '#00b0ff';
          ctx.lineWidth = 1.5;
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(x1, padTop, boxW, plotH);
          ctx.setLineDash([]);
        }
