                </div>
                <span style="font-size: 8.5px; color: #64748b; font-family: monospace; white-space: nowrap;">In: ${formatTrafficBps(item.inBps)} &bull; Out: ${formatTrafficBps(item.outBps)}</span>
              </div>
            </div>
