                el.style.border = '1px solid #00b0ff';
                el.style.boxShadow = '0 0 8px rgba(0, 176, 255, 0.4)';
              } else {
                el.style.border = '1px solid #1e293b';
                el.style.boxShadow = 'none';
              }
            });
          }
        } catch (e) {}

        // Update Detail Panel
