            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              jsonrpc: '2.0',
              method: 'problem.get',
              params: {
                hostids: ['10682']
              },
              auth: '{{ZABBIX_API_TOKEN}}',
              id: Date.now() + 1
            })
          }),
          fetch('http://{{ZABBIX_HOST}}/api_jsonrpc.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              jsonrpc: '2.0',
              method: 'event.get',
              params: {
                hostids: ['10682'],
                limit: 5,
                sortfield: 'clock',
                sortorder: 'DESC',
                output: ['eventid', 'clock', 'value', 'name', 'severity']
              },
              auth: '{{ZABBIX_API_TOKEN}}',
              id: Date.now() + 2
            })
          }),
          fetch('http://{{ZABBIX_HOST}}/api_jsonrpc.php', {
